import React, { useEffect, useState } from 'react';
import {
  Box, Typography, Paper, TextField, Button, Snackbar, Alert,
  Dialog, DialogTitle, DialogContent, DialogActions, FormControl, FormHelperText
} from '@mui/material';
import { useAuth } from './AuthContext';

const ProfileTab = () => {
  const { user, updateUser } = useAuth();
  const [profile, setProfile] = useState({
    firstName: '',
    lastName: '',
    username: '',
  });
  const [lastUpdated, setLastUpdated] = useState({
    username: null,
    password: null
  });
  const [openPasswordDialog, setOpenPasswordDialog] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmNewPassword, setConfirmNewPassword] = useState('');
  const [currentPassword, setCurrentPassword] = useState('');
  const [passwordConfirm, setPasswordConfirm] = useState('');
  const [usernameConfirm, setUsernameConfirm] = useState('');
  const [errors, setErrors] = useState({
    username: '',
    password: '',
    confirmPassword: '',
    currentPassword: '',
    usernameConfirm: '',
    passwordConfirm: ''
  });
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });
  const [editingUsername, setEditingUsername] = useState(false);

  useEffect(() => {
    fetchProfile();
    fetchLastUpdated();
  }, []);

  const fetchProfile = async () => {
    // In a real app, you would fetch the profile from an API
    // For this example, we'll use the user from the Auth context
    if (user) {
      setProfile({
        firstName: user.firstName || '',
        lastName: user.lastName || '',
        username: user.username || '',
      });
    }
  };

  const fetchLastUpdated = async () => {
    try {
      // In a real app, you would fetch this data from an API
      // For this example, we'll check localStorage
      const storedData = localStorage.getItem(`lastUpdated_${user.workerID}`);
      if (storedData) {
        setLastUpdated(JSON.parse(storedData));
      }
    } catch (error) {
      console.error('Error fetching last updated information:', error);
    }
  };

  const canUpdateToday = (field) => {
    if (!lastUpdated[field]) return true;

    const lastDate = new Date(lastUpdated[field]);
    const today = new Date();

    // Reset hours, minutes, seconds and milliseconds for date comparison
    lastDate.setHours(0, 0, 0, 0);
    today.setHours(0, 0, 0, 0);

    // If the dates are different (i.e., not the same day), then update is allowed
    return lastDate.getTime() !== today.getTime();
  };

  const handleUsernameEdit = () => {
    setEditingUsername(true);
    setUsernameConfirm('');
    setErrors({...errors, usernameConfirm: '', username: ''});
  };

  const handleCancelUsernameEdit = () => {
    setEditingUsername(false);
    setProfile({...profile, username: user.username});
    setUsernameConfirm('');
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile({...profile, [name]: value});

    if (name === 'username') {
      setErrors({...errors, username: ''});
    }
  };

  const handlePasswordChange = (e) => {
    const { name, value } = e.target;

    if (name === 'newPassword') {
      setNewPassword(value);
      setErrors({...errors, password: ''});
    } else if (name === 'confirmNewPassword') {
      setConfirmNewPassword(value);
      setErrors({...errors, confirmPassword: ''});
    } else if (name === 'currentPassword') {
      setCurrentPassword(value);
      setErrors({...errors, currentPassword: ''});
    } else if (name === 'passwordConfirm') {
      setPasswordConfirm(value);
      setErrors({...errors, passwordConfirm: ''});
    } else if (name === 'usernameConfirm') {
      setUsernameConfirm(value);
      setErrors({...errors, usernameConfirm: ''});
    }
  };

  const openChangePasswordDialog = () => {
    if (!canUpdateToday('password')) {
      setSnackbar({
        open: true,
        message: 'You can only change your password once per day.',
        severity: 'warning'
      });
      return;
    }

    setNewPassword('');
    setConfirmNewPassword('');
    setCurrentPassword('');
    setPasswordConfirm('');
    setErrors({
      ...errors,
      password: '',
      confirmPassword: '',
      currentPassword: '',
      passwordConfirm: ''
    });
    setOpenPasswordDialog(true);
  };

  const closePasswordDialog = () => {
    setOpenPasswordDialog(false);
  };

  const validatePassword = (password) => {
    if (!password) return "Password is required";

    const minLength = 8;
    const specialCharRegex = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]+/;

    if (password.length < minLength) {
      return "Password must be at least 8 characters long";
    }

    if (!specialCharRegex.test(password)) {
      return "Password must contain at least one special character";
    }

    return "";
  };

  const verifyPassword = async (password) => {
    // In a real app, you would verify the password with an API
    // For this example, we'll assume any non-empty password is valid
    if (!password) {
      return false;
    }

    // Mock API call to verify password
    return true;
  };

  const handleUsernameUpdate = async () => {
    // Check if username can be updated today
    if (!canUpdateToday('username')) {
      setSnackbar({
        open: true,
        message: 'You can only change your username once per day.',
        severity: 'warning'
      });
      return;
    }

    // Validate input
    let valid = true;
    const newErrors = {...errors};

    if (!profile.username) {
      newErrors.username = "Username is required";
      valid = false;
    }

    if (!usernameConfirm) {
      newErrors.usernameConfirm = "Please enter your password to confirm";
      valid = false;
    }

    setErrors(newErrors);
    if (!valid) return;

    // Verify password
    const isPasswordValid = await verifyPassword(usernameConfirm);
    if (!isPasswordValid) {
      setErrors({...errors, usernameConfirm: "Incorrect password"});
      return;
    }

    try {
      // In a real app, you would update the username through an API
      // Mock API call

      // Update last updated timestamp
      const updatedTimestamps = {
        ...lastUpdated,
        username: new Date().toISOString()
      };
      localStorage.setItem(`lastUpdated_${user.workerID}`, JSON.stringify(updatedTimestamps));
      setLastUpdated(updatedTimestamps);

      // Update user context
      updateUser({...user, username: profile.username});

      setEditingUsername(false);
      setSnackbar({
        open: true,
        message: 'Username updated successfully',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error updating username:', error);
      setSnackbar({
        open: true,
        message: 'Error updating username',
        severity: 'error'
      });
    }
  };

  const handleChangePassword = async () => {
    // Validate input
    let valid = true;
    const newErrors = {...errors};

    const passwordError = validatePassword(newPassword);
    if (passwordError) {
      newErrors.password = passwordError;
      valid = false;
    }

    if (newPassword !== confirmNewPassword) {
      newErrors.confirmPassword = "Passwords do not match";
      valid = false;
    }

    if (!currentPassword) {
      newErrors.currentPassword = "Current password is required";
      valid = false;
    }

    if (!passwordConfirm) {
      newErrors.passwordConfirm = "Please enter your password again to confirm";
      valid = false;
    }

    setErrors(newErrors);
    if (!valid) return;

    // Verify current password
    const isCurrentPasswordValid = await verifyPassword(currentPassword);
    if (!isCurrentPasswordValid) {
      setErrors({...errors, currentPassword: "Incorrect password"});
      return;
    }

    // Verify confirmation password
    const isConfirmValid = await verifyPassword(passwordConfirm);
    if (!isConfirmValid) {
      setErrors({...errors, passwordConfirm: "Incorrect password"});
      return;
    }

    try {
      // In a real app, you would update the password through an API
      // Mock API call

      // Update last updated timestamp
      const updatedTimestamps = {
        ...lastUpdated,
        password: new Date().toISOString()
      };
      localStorage.setItem(`lastUpdated_${user.workerID}`, JSON.stringify(updatedTimestamps));
      setLastUpdated(updatedTimestamps);

      closePasswordDialog();
      setSnackbar({
        open: true,
        message: 'Password updated successfully',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error updating password:', error);
      setSnackbar({
        open: true,
        message: 'Error updating password',
        severity: 'error'
      });
    }
  };

  const handleCloseSnackbar = () => {
    setSnackbar({...snackbar, open: false});
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 'bold', textAlign: 'center', mb: 4 }}>
        My Profile
      </Typography>

      <Paper elevation={3} sx={{ p: 3, maxWidth: 600, mx: 'auto' }}>
        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 2 }}>
            Personal Information
          </Typography>

          <FormControl fullWidth margin="normal">
            <TextField
              label="First Name"
              value={profile.firstName}
              fullWidth
              margin="dense"
              disabled
            />
            <FormHelperText>
              Your first name cannot be changed. Please contact an administrator for assistance.
            </FormHelperText>
          </FormControl>

          <FormControl fullWidth margin="normal">
            <TextField
              label="Last Name"
              value={profile.lastName}
              fullWidth
              margin="dense"
              disabled
            />
            <FormHelperText>
              Your last name cannot be changed. Please contact an administrator for assistance.
            </FormHelperText>
          </FormControl>
        </Box>

        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 2 }}>
            Account Information
          </Typography>

          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            {editingUsername ? (
              <>
                <FormControl fullWidth margin="normal">
                  <TextField
                    label="New Username"
                    name="username"
                    value={profile.username}
                    onChange={handleChange}
                    fullWidth
                    margin="dense"
                    error={!!errors.username}
                    helperText={errors.username}
                  />
                  <FormHelperText>
                    You can only change your username once per day.
                  </FormHelperText>
                </FormControl>

                <FormControl fullWidth margin="normal">
                  <TextField
                    label="Enter Your Password to Confirm"
                    name="usernameConfirm"
                    type="password"
                    value={usernameConfirm}
                    onChange={handlePasswordChange}
                    fullWidth
                    margin="dense"
                    error={!!errors.usernameConfirm}
                    helperText={errors.usernameConfirm}
                    required
                  />
                </FormControl>

                <Box sx={{ display: 'flex', gap: 2, justifyContent: 'flex-end', mt: 1 }}>
                  <Button onClick={handleCancelUsernameEdit}>
                    Cancel
                  </Button>
                  <Button 
                    onClick={handleUsernameUpdate} 
                    variant="contained" 
                    color="primary"
                  >
                    Save Changes
                  </Button>
                </Box>
              </>
            ) : (
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <TextField
                  label="Username"
                  value={profile.username}
                  fullWidth
                  margin="dense"
                  disabled
                />
                <Button 
                  onClick={handleUsernameEdit} 
                  variant="contained" 
                  color="primary"
                  sx={{ mt: 1 }}
                >
                  Change
                </Button>
              </Box>
            )}

            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mt: 2 }}>
              <TextField
                label="Password"
                type="password"
                value="••••••••"
                fullWidth
                margin="dense"
                disabled
              />
              <Button 
                onClick={openChangePasswordDialog} 
                variant="contained" 
                color="primary"
                sx={{ mt: 1 }}
              >
                Change
              </Button>
            </Box>
          </Box>
        </Box>
      </Paper>

      {/* Password Change Dialog */}
      <Dialog open={openPasswordDialog} onClose={closePasswordDialog} maxWidth="sm" fullWidth>
        <DialogTitle>Change Password</DialogTitle>
        <DialogContent>
          <Box sx={{ py: 1 }}>
            <FormControl fullWidth margin="normal">
              <TextField
                label="Current Password"
                name="currentPassword"
                type="password"
                value={currentPassword}
                onChange={handlePasswordChange}
                fullWidth
                required
                error={!!errors.currentPassword}
                helperText={errors.currentPassword}
              />
            </FormControl>

            <FormControl fullWidth margin="normal">
              <TextField
                label="New Password"
                name="newPassword"
                type="password"
                value={newPassword}
                onChange={handlePasswordChange}
                fullWidth
                required
                error={!!errors.password}
                helperText={errors.password || "Must be at least 8 characters with 1 special character"}
              />
            </FormControl>

            <FormControl fullWidth margin="normal">
              <TextField
                label="Confirm New Password"
                name="confirmNewPassword"
                type="password"
                value={confirmNewPassword}
                onChange={handlePasswordChange}
                fullWidth
                required
                error={!!errors.confirmPassword}
                helperText={errors.confirmPassword}
              />
            </FormControl>

            <Typography variant="subtitle2" sx={{ mt: 2, mb: 1 }}>
              Confirm Action
            </Typography>

            <FormControl fullWidth margin="normal">
              <TextField
                label="Enter Your Password Again to Confirm"
                name="passwordConfirm"
                type="password"
                value={passwordConfirm}
                onChange={handlePasswordChange}
                fullWidth
                required
                error={!!errors.passwordConfirm}
                helperText={errors.passwordConfirm}
              />
              <FormHelperText>
                You can only change your password once per day.
              </FormHelperText>
            </FormControl>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={closePasswordDialog}>Cancel</Button>
          <Button 
            onClick={handleChangePassword} 
            variant="contained" 
            color="primary"
            disabled={!currentPassword || !newPassword || !confirmNewPassword || !passwordConfirm}
          >
            Update Password
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleCloseSnackbar} 
          severity={snackbar.severity} 
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ProfileTab;
